    if (this.#nodes === undefined) {
      throw new Error('Nodes are not set');
    }
    return this.#nodes;
  }

  set nodes(nodes: GraphNode[]) {
    // a unique, insertion-ordered collection of nodes
    this.#nodes = [...new Set(nodes)];
  }
}

